function Get-ADChildGroups {
    param([string]$GroupIdentity)   # accepts name or DN

    try {
        $parent = Get-ADGroup -Identity $GroupIdentity -Properties member -ErrorAction Stop
    } catch {
        return @{ Found = $false; Children = @() }
    }

    # Children = members that are themselves groups
    $children = foreach ($dn in $parent.member) {
        $obj = Get-ADObject -Identity $dn -Properties objectClass
        if ($obj.objectClass -eq 'group') {
            Get-ADGroup -Identity $dn | Select-Object Name, DistinguishedName
        }
    }
    return @{ Found = $true; Parent = $parent; Children = @($children) }
}

function Get-ADSources {
    param([hashtable]$Headers)
    Write-Log "Discovering Active Directory sources in tenant..." "INFO"

    $sources   = Invoke-ISCPagedGet -Endpoint "/v2025/sources" -Headers $Headers
    $adSources = $sources | Where-Object {
        $_.type -like "*Active Directory*" -or
        $_.connectorName -like "*Active Directory*"
    }

    foreach ($src in $adSources) {
        Write-Log "  Found AD source: $($src.name) (ID: $($src.id))" "INFO"
    }
    return $adSources
}

function Resolve-RoleOwner {
    param([object]$ParentEntitlement, [hashtable]$Headers)

    if ($ParentEntitlement.owner -and $ParentEntitlement.owner.id) {
        return @{ Id = $ParentEntitlement.owner.id; Name = $ParentEntitlement.owner.name; Fallback = $false }
    }

    # No owner on the entitlement - fall back and record it
    $fallback = Get-ISCIdentityByName -Name $DefaultOwnerName -Headers $Headers
    $script:MissingOwners += [pscustomobject]@{
        ParentGroup   = $ParentEntitlement.name
        Source        = $ParentEntitlement.sourceName
        ResolvedOwner = "Fallback: $($fallback.name)"
        Reason        = "No entitlement owner in ISC"
    }
    Write-Log "No owner for '$($ParentEntitlement.name)' - using fallback '$($fallback.name)'" "WARN"
    return @{ Id = $fallback.id; Name = $fallback.name; Fallback = $true }
}

$rolePayload = @{
    name         = "NGR - $($parent.name)"
    description  = "Auto-generated role representing children of nested AD group '$($parent.name)' for composition certification."
    owner        = @{ id = $owner.Id; type = "IDENTITY" }
    entitlements = @($children | ForEach-Object { @{ id = $_.id; type = "ENTITLEMENT" } })
}

$existing = Get-ISCRoleByName -Name $rolePayload.name -Headers $headers
if ($existing) {
    if (Compare-EntitlementLists $existing.entitlements $rolePayload.entitlements) {
        Write-Log "Role '$($rolePayload.name)' already correct - no-op" "INFO"
        $counts.Unchanged++
    } elseif ($DryRun) {
        Write-Log "DRYRUN: Would PATCH role '$($rolePayload.name)'" "DRYRUN"; $counts.Simulated++
    } else {
        Invoke-ISCSafe -Uri "https://$TenantUrl/v2025/roles/$($existing.id)" -Method PATCH -Headers $headers -Body $patchBody | Out-Null
        Write-Log "Patched role: $($rolePayload.name)" "AUDIT"; $counts.Patched++
    }
} elseif ($DryRun) {
    Write-Log "DRYRUN: Would POST role '$($rolePayload.name)' with $($children.Count) children" "DRYRUN"; $counts.Simulated++
} else {
    $role = Invoke-ISCSafe -Uri "https://$TenantUrl/v2025/roles" -Method POST -Headers $headers -Body $rolePayload
    Write-Log "Created role: $($role.name) (ID: $($role.id))" "AUDIT"; $counts.RolesCreated++
}

# Phase 4 example: ROLE_COMPOSITION campaigns from the role manifest
$payloads | ConvertTo-Json -Depth 10 |
    Set-Content -Path (Join-Path $OutputPath "CampaignPayloads_${OutputTag}_$ts.json")
Write-Log "Wrote $($payloads.Count) campaign payload(s) to file" "INFO"

if ($PostCampaigns -and -not $DryRun) {
    foreach ($p in $payloads) {
        $campaign = Invoke-ISCSafe -Uri "https://$TenantUrl/v2025/campaigns" -Method POST -Headers $headers -Body $p
        Write-Log "Created campaign: $($p.name) (ID: $($campaign.id))" "AUDIT"
        $counts.CampaignsCreated++
    }
} else {
    Write-Log "PostCampaigns not set (or DryRun) - payloads written to file only" "INFO"
}
